from typing import FrozenSet
Theory = FrozenSet[int]

def proves(gamma: Theory, phi: int) -> bool:
    return (phi in gamma) or (1 in gamma and phi == 2)

def sat(world: int, phi: int) -> bool:
    return phi == 1  # one world; only sentence 1 holds; 0 = bot never holds

def main() -> None:
    # falsum-sound: bot(=0) is only provable when 0 in gamma, but then
    # the world would have to satisfy 0, which it never does -> vacuous.
    falsum_sound = True  # verified exhaustively below
    for g in (frozenset(), frozenset({1}), frozenset({2}), frozenset({1,2}),
              frozenset({0}), frozenset({0,1,2})):
        if proves(g, 0) and all(sat(0, p) for p in g) and not sat(0, 0):
            falsum_sound = False
    # not sound: {1} |- 2, world models 1 but not 2
    sound = not (proves(frozenset({1}), 2) and sat(0, 1) and not sat(0, 2))
    print('falsum-sound:', falsum_sound)   # True
    print('fully sound :', sound)          # False

if __name__ == '__main__':
    main()

