    # P.proves: (theory, sentence) -> bool ; P.bot: sentence
    return not P.proves(T, P.bot)

function decide_physical_consistency(M, T):
    for w in M.worlds:
        if for all phi in T: M.sat(w, phi):
            return True
    return False

function is_sound(P, M):
    for Gamma in powerset(P.sentences):
        for phi in P.sentences:
            if P.proves(Gamma, phi):
                for w in M.worlds:
                    if (for all psi in Gamma: M.sat(w,psi)) and not M.sat(w,phi):
                        return False
    return True

function is_falsum_sound(P, M):
